  s.ward IN ('Xuân Hòa','Cầu Ông Lãnh','Bàn Cờ')
  AND s.category IN ('nha_sach','van_phong_pham')
  AND s.source LIKE 'https://%'
  AND s.address_new LIKE '%phường '||s.ward||'%'
  AND (s.phone IS NULL OR s.phone ~ '^[0-9]{8,11}$')
  AND (s.place IS NULL OR s.place ~ '^ChIJ[A-Za-z0-9_-]{20,}$')
  AND EXISTS (SELECT 1 FROM public.sales_hcm_old_wards w WHERE w.province='TP Hồ Chí Minh' AND w.ward_new=s.ward AND w.legacy_district=s.district AND w.active)
  AND NOT EXISTS (SELECT 1 FROM public.field_prospects p WHERE p.research_source_key=s.key OR (s.place IS NOT NULL AND p.google_place_id=s.place)
    OR lower(btrim(p.address_line))=lower(btrim(s.address_new))
    OR (p.province='TP Hồ Chí Minh' AND p.ward_new=s.ward AND lower(btrim(p.name))=lower(btrim(s.name)))
    OR (s.phone IS NOT NULL AND regexp_replace(coalesce(p.phone,''),'[^0-9]','','g')=s.phone))
  AND NOT EXISTS (SELECT 1 FROM public.customers c WHERE lower(btrim(c.address_line))=lower(btrim(s.address_new))
    OR (c.province='TP Hồ Chí Minh' AND lower(btrim(c.name))=lower(btrim(s.name)))
    OR (s.phone IS NOT NULL AND regexp_replace(coalesce(c.phone,''),'[^0-9]','','g')=s.phone))
), inserted AS (
 INSERT INTO public.field_prospects (
 id,area_visit_id,owner_sub,name,address_line,province,district,ward_new,address_legacy,
 category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,
 research_batch,google_maps_url,google_place_id)
 SELECT gen_random_uuid(),NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_new,
   'TP Hồ Chí Minh',s.district,s.ward,s.address_old,s.category,s.phone,NULL,
   'Nguồn tra cứu 22/11/2026; CHƯA GHÉ / CHƯA XÁC MINH hoạt động và GPS tại quầy. '||
   s.proof||' Nguồn: '||s.source,
   'new','manual',s.key,s.source,'2026-11-22-hcm-old-three-new-wards-first-176',s.gmaps,s.place
 FROM vetted s
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING ward_new,name,category,phone,google_place_id)
SELECT ward_new,name,category,phone,google_place_id FROM inserted ORDER BY ward_new,name;